CREATE TABLE public.assignment_config (id uuid DEFAULT gen_random_uuid() NOT NULL, urgency text NOT NULL, plan_type text NOT NULL, timer_minutes integer NOT NULL, max_attempts integer DEFAULT 3, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.assignment_logs (id uuid DEFAULT gen_random_uuid() NOT NULL, request_id uuid NOT NULL, plumber_id uuid NOT NULL, plumber_plan text NOT NULL, assigned_at timestamptz DEFAULT now() NOT NULL, expires_at timestamptz NOT NULL, responded boolean DEFAULT false, response_type text, response_at timestamptz, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.contact_logs (id uuid DEFAULT gen_random_uuid() NOT NULL, plumber_id uuid NOT NULL, request_id uuid NOT NULL, contacted_at timestamptz DEFAULT now());
CREATE TABLE public.contact_unlocks (id uuid DEFAULT gen_random_uuid() NOT NULL, plumber_id uuid NOT NULL, request_id uuid NOT NULL, is_exclusive boolean DEFAULT false NOT NULL, unlocked_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.conversation_messages (id uuid DEFAULT gen_random_uuid() NOT NULL, conversation_id uuid NOT NULL, sender_type text NOT NULL, content text NOT NULL, read_by_recipient boolean DEFAULT false NOT NULL, created_at timestamptz DEFAULT now() NOT NULL,
  CONSTRAINT conversation_messages_content_check CHECK (length(content) >= 1 AND length(content) <= 4000),
  CONSTRAINT conversation_messages_sender_type_check CHECK (sender_type = ANY (ARRAY['plumber'::text, 'client'::text])));
CREATE TABLE public.conversations (id uuid DEFAULT gen_random_uuid() NOT NULL, request_id uuid NOT NULL, plumber_id uuid NOT NULL, client_access_token text DEFAULT encode(extensions.gen_random_bytes(32), 'hex') NOT NULL, quote_amount_cents integer, last_message_at timestamptz DEFAULT now() NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.credit_packages (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, credits integer NOT NULL, price_cents integer NOT NULL, price_per_credit numeric(10,2) NOT NULL, stripe_price_id text, is_active boolean DEFAULT true NOT NULL, sort_order integer DEFAULT 0 NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL, amount_cents integer DEFAULT 0 NOT NULL);
CREATE TABLE public.credit_transactions (id uuid DEFAULT gen_random_uuid() NOT NULL, plumber_id uuid NOT NULL, transaction_type text NOT NULL, credits integer NOT NULL, balance_after integer NOT NULL, package_id uuid, stripe_payment_intent_id text, amount_cents integer, request_id uuid, unlock_reason text, description text, created_at timestamptz DEFAULT now() NOT NULL, amount_cents_delta integer DEFAULT 0 NOT NULL, balance_after_cents integer DEFAULT 0 NOT NULL,
  CONSTRAINT credit_transactions_transaction_type_check CHECK (transaction_type = ANY (ARRAY['purchase'::text, 'unlock'::text, 'refund'::text, 'bonus'::text])));
CREATE TABLE public.intervention_pricing (intervention_type public.intervention_type NOT NULL, tier text NOT NULL, multiplier numeric DEFAULT 1.0 NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.italian_cities (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, province_code text NOT NULL, province_name text NOT NULL, region text NOT NULL, cap text[] DEFAULT '{}'::text[] NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.plumber_credits (id uuid DEFAULT gen_random_uuid() NOT NULL, plumber_id uuid NOT NULL, balance integer DEFAULT 0 NOT NULL, total_purchased integer DEFAULT 0 NOT NULL, total_spent integer DEFAULT 0 NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL, balance_cents integer DEFAULT 0 NOT NULL, total_purchased_cents integer DEFAULT 0 NOT NULL, total_spent_cents integer DEFAULT 0 NOT NULL);
CREATE TABLE public.plumber_profiles (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, full_name text NOT NULL, business_name text NOT NULL, email text NOT NULL, phone text NOT NULL, main_city text NOT NULL, description text, intervention_types public.intervention_type[] DEFAULT '{}'::public.intervention_type[], availability public.availability_type[] DEFAULT '{}'::public.availability_type[], service_areas text[] DEFAULT '{}'::text[], email_verified boolean DEFAULT false, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), photo_url text, rating numeric(2,1) DEFAULT 0, review_count integer DEFAULT 0);
CREATE TABLE public.plumber_subscriptions (id uuid DEFAULT gen_random_uuid() NOT NULL, plumber_id uuid NOT NULL, plan_type public.subscription_plan NOT NULL, status public.subscription_status DEFAULT 'pending'::public.subscription_status NOT NULL, current_period_start timestamptz, current_period_end timestamptz, exclusive_contacts_used integer DEFAULT 0 NOT NULL, stripe_customer_id text, stripe_subscription_id text, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL, trial_ends_at timestamptz, monthly_contact_limit integer, monthly_contacts_used integer DEFAULT 0, contacts_reset_at timestamptz DEFAULT now(), is_available boolean DEFAULT true, last_assigned_at timestamptz, free_requests_remaining integer DEFAULT 3, is_trial boolean DEFAULT true);
CREATE TABLE public.service_requests (id uuid DEFAULT gen_random_uuid() NOT NULL, intervention_type public.intervention_type NOT NULL, city text NOT NULL, description text NOT NULL, urgency public.urgency_type NOT NULL, property_type public.property_type NOT NULL, accessibility public.accessibility_type NOT NULL, client_name text NOT NULL, client_phone text NOT NULL, client_email text, privacy_accepted boolean DEFAULT false NOT NULL, status text DEFAULT 'new'::text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), assigned_plumber_id uuid, is_exclusive boolean DEFAULT false NOT NULL, assigned_at timestamptz, assignment_started_at timestamptz, assignment_expires_at timestamptz, assignment_round integer DEFAULT 0, accepted_at timestamptz, accepted_by_id uuid, current_assignee_plan text, wizard_answers jsonb, client_user_id uuid, phone_contact_allowed boolean DEFAULT true NOT NULL);
CREATE TABLE public.service_requests_public_meta (request_id uuid NOT NULL, city text NOT NULL, intervention_type public.intervention_type NOT NULL, urgency public.urgency_type NOT NULL, property_type public.property_type NOT NULL, accessibility public.accessibility_type NOT NULL, status text DEFAULT 'new'::text NOT NULL, is_exclusive boolean DEFAULT false NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.subscription_plans (id uuid DEFAULT gen_random_uuid() NOT NULL, plan_type public.subscription_plan NOT NULL, name text NOT NULL, description text, price_monthly numeric(10,2) NOT NULL, max_exclusive_contacts integer, contacts_are_exclusive boolean DEFAULT false NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.unlock_costs (id uuid DEFAULT gen_random_uuid() NOT NULL, urgency text NOT NULL, credits_cost integer NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL, cost_cents integer DEFAULT 0 NOT NULL);
CREATE TABLE public.unregistered_plumbers (id uuid DEFAULT gen_random_uuid() NOT NULL, full_name text NOT NULL, phone text NOT NULL, city text DEFAULT 'Napoli'::text NOT NULL, is_active boolean DEFAULT true NOT NULL, notes text, created_at timestamptz DEFAULT now() NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.whatsapp_logs (id uuid DEFAULT gen_random_uuid() NOT NULL, recipient_phone text NOT NULL, recipient_name text, message_type text DEFAULT 'assignment'::text NOT NULL, request_id uuid, plumber_id uuid, status text DEFAULT 'pending'::text NOT NULL, error_message text, respond_io_message_id text, created_at timestamptz DEFAULT now() NOT NULL, delivered_at timestamptz, read_at timestamptz);

