CREATE TRIGGER normalize_city_trigger BEFORE INSERT OR UPDATE OF city ON public.service_requests FOR EACH ROW EXECUTE FUNCTION public.normalize_service_request_city();
CREATE TRIGGER normalize_service_areas_trigger BEFORE INSERT OR UPDATE OF service_areas, main_city ON public.plumber_profiles FOR EACH ROW EXECUTE FUNCTION public.normalize_plumber_service_areas();
