CREATE POLICY "Admins can delete profiles" ON public.plumber_profiles FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage all assignment logs" ON public.assignment_logs USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage all contact unlocks" ON public.contact_unlocks USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage all credits" ON public.plumber_credits USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage all requests" ON public.service_requests TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage all subscriptions" ON public.plumber_subscriptions USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage all transactions" ON public.credit_transactions USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage assignment config" ON public.assignment_config USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage credit packages" ON public.credit_packages USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage public request meta" ON public.service_requests_public_meta USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage subscription plans" ON public.subscription_plans USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage unlock costs" ON public.unlock_costs USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can manage unregistered plumbers" ON public.unregistered_plumbers USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can update all profiles" ON public.plumber_profiles FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can view all contacts" ON public.contact_logs FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can view all profiles" ON public.plumber_profiles FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can view all whatsapp logs" ON public.whatsapp_logs FOR SELECT USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins manage all conversations" ON public.conversations USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins manage all messages" ON public.conversation_messages USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins manage intervention pricing" ON public.intervention_pricing USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Anyone can create service requests" ON public.service_requests FOR INSERT TO anon, authenticated WITH CHECK (privacy_accepted = true);
CREATE POLICY "Anyone can view active credit packages" ON public.credit_packages FOR SELECT USING (is_active = true);
CREATE POLICY "Anyone can view assignment config" ON public.assignment_config FOR SELECT USING (true);
CREATE POLICY "Anyone can view cities" ON public.italian_cities FOR SELECT USING (true);
CREATE POLICY "Anyone can view intervention pricing" ON public.intervention_pricing FOR SELECT USING (true);
CREATE POLICY "Anyone can view subscription plans" ON public.subscription_plans FOR SELECT USING (true);
CREATE POLICY "Anyone can view unlock costs" ON public.unlock_costs FOR SELECT USING (true);
CREATE POLICY "Clients insert messages on own conversations" ON public.conversation_messages FOR INSERT TO authenticated WITH CHECK (sender_type = 'client' AND EXISTS (SELECT 1 FROM public.conversations c JOIN public.service_requests sr ON sr.id = c.request_id WHERE c.id = conversation_messages.conversation_id AND (sr.client_user_id = auth.uid() OR (sr.client_email IS NOT NULL AND lower(sr.client_email) = lower(COALESCE(auth.jwt() ->> 'email', ''))))));
CREATE POLICY "Clients see messages on own conversations" ON public.conversation_messages FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.conversations c JOIN public.service_requests sr ON sr.id = c.request_id WHERE c.id = conversation_messages.conversation_id AND (sr.client_user_id = auth.uid() OR (sr.client_email IS NOT NULL AND lower(sr.client_email) = lower(COALESCE(auth.jwt() ->> 'email', ''))))));
CREATE POLICY "Clients see own conversations" ON public.conversations FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.service_requests sr WHERE sr.id = conversations.request_id AND (sr.client_user_id = auth.uid() OR (sr.client_email IS NOT NULL AND lower(sr.client_email) = lower(COALESCE(auth.jwt() ->> 'email', ''))))));
CREATE POLICY "Clients view own requests" ON public.service_requests FOR SELECT TO authenticated USING (client_user_id = auth.uid());
CREATE POLICY "Clients view requests matching own email" ON public.service_requests FOR SELECT TO authenticated USING (client_email IS NOT NULL AND lower(client_email) = lower(COALESCE(auth.jwt() ->> 'email', '')));
CREATE POLICY "Deny anon select plumber_profiles" ON public.plumber_profiles FOR SELECT TO anon USING (false);
CREATE POLICY "Deny anon select service_requests" ON public.service_requests FOR SELECT TO anon USING (false);
CREATE POLICY "Nobody can delete contact logs" ON public.contact_logs FOR DELETE TO authenticated USING (false);
CREATE POLICY "Nobody can delete contact unlocks" ON public.contact_unlocks FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Nobody can update contact logs" ON public.contact_logs FOR UPDATE TO authenticated USING (false);
CREATE POLICY "Nobody can update contact unlocks" ON public.contact_unlocks FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Plumbers can create own unlocks" ON public.contact_unlocks FOR INSERT WITH CHECK (EXISTS (SELECT 1 FROM public.plumber_profiles WHERE plumber_profiles.id = contact_unlocks.plumber_id AND plumber_profiles.user_id = auth.uid()));
CREATE POLICY "Plumbers can insert their own profile" ON public.plumber_profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Plumbers can log their contacts" ON public.contact_logs FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.plumber_profiles WHERE plumber_profiles.id = contact_logs.plumber_id AND plumber_profiles.user_id = auth.uid()));
CREATE POLICY "Plumbers can update their own profile" ON public.plumber_profiles FOR UPDATE TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "Plumbers can view own credits" ON public.plumber_credits FOR SELECT USING (EXISTS (SELECT 1 FROM public.plumber_profiles WHERE plumber_profiles.id = plumber_credits.plumber_id AND plumber_profiles.user_id = auth.uid()));
CREATE POLICY "Plumbers can view own subscription" ON public.plumber_subscriptions FOR SELECT USING (EXISTS (SELECT 1 FROM public.plumber_profiles WHERE plumber_profiles.id = plumber_subscriptions.plumber_id AND plumber_profiles.user_id = auth.uid()));
CREATE POLICY "Plumbers can view own transactions" ON public.credit_transactions FOR SELECT USING (EXISTS (SELECT 1 FROM public.plumber_profiles WHERE plumber_profiles.id = credit_transactions.plumber_id AND plumber_profiles.user_id = auth.uid()));
CREATE POLICY "Plumbers can view own unlocks" ON public.contact_unlocks FOR SELECT USING (EXISTS (SELECT 1 FROM public.plumber_profiles WHERE plumber_profiles.id = contact_unlocks.plumber_id AND plumber_profiles.user_id = auth.uid()));
CREATE POLICY "Plumbers can view public request meta" ON public.service_requests_public_meta FOR SELECT USING (public.is_plumber(auth.uid()) OR public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Plumbers can view their assigned requests" ON public.service_requests FOR SELECT TO authenticated USING (assigned_plumber_id IN (SELECT pp.id FROM public.plumber_profiles pp WHERE pp.user_id = auth.uid()) OR accepted_by_id IN (SELECT pp.id FROM public.plumber_profiles pp WHERE pp.user_id = auth.uid()) OR public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Plumbers can view their contacts" ON public.contact_logs FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.plumber_profiles WHERE plumber_profiles.id = contact_logs.plumber_id AND plumber_profiles.user_id = auth.uid()));
CREATE POLICY "Plumbers can view their own assignment logs" ON public.assignment_logs FOR SELECT USING (EXISTS (SELECT 1 FROM public.plumber_profiles WHERE plumber_profiles.id = assignment_logs.plumber_id AND plumber_profiles.user_id = auth.uid()));
CREATE POLICY "Plumbers can view their own profile" ON public.plumber_profiles FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "Plumbers insert own messages" ON public.conversation_messages FOR INSERT WITH CHECK (sender_type = 'plumber' AND EXISTS (SELECT 1 FROM public.conversations c JOIN public.plumber_profiles pp ON pp.id = c.plumber_id WHERE c.id = conversation_messages.conversation_id AND pp.user_id = auth.uid()));
CREATE POLICY "Plumbers see own conversations" ON public.conversations FOR SELECT USING (EXISTS (SELECT 1 FROM public.plumber_profiles pp WHERE pp.id = conversations.plumber_id AND pp.user_id = auth.uid()));
CREATE POLICY "Plumbers see own messages" ON public.conversation_messages FOR SELECT USING (EXISTS (SELECT 1 FROM public.conversations c JOIN public.plumber_profiles pp ON pp.id = c.plumber_id WHERE c.id = conversation_messages.conversation_id AND pp.user_id = auth.uid()));
CREATE POLICY "Plumbers update own conversations" ON public.conversations FOR UPDATE USING (EXISTS (SELECT 1 FROM public.plumber_profiles pp WHERE pp.id = conversations.plumber_id AND pp.user_id = auth.uid()));

ALTER PUBLICATION supabase_realtime ADD TABLE public.conversations;
ALTER PUBLICATION supabase_realtime ADD TABLE public.conversation_messages;